echo "=== hooks tool counts (today) ==="; python3 -c "
import json,collections
c=collections.Counter(); t=collections.Counter(); n=collections.Counter()
for line in open('.workflow/telemetry/hooks-2026-06-20.jsonl'):
    try: r=json.loads(line)
    except: continue
    tool=r.get('tool','?'); c[tool]+=1; t[tool]+=r.get('est_tokens',0) or 0
for k in c: n[k]=round(t[k]/c[k]) if c[k] else 0
for k,v in c.most_common(): print(f'{k}: {v} calls, avg_est_tokens={n[k]}')
"
